from collections import defaultdict, deque

class Solution:
    def frogPosition(self, n, edges, t, target):
        adj = defaultdict(list)
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        q = deque([(1, 0, 1.0, 0)])
        seen = {1}
        while q:
            node, par, prob, time = q.popleft()
            children = [nb for nb in adj[node] if nb != par]
            if node == target:
                if time == t or (time < t and not children):
                    return prob
                return 0.0
            if time < t:
                for c in children:
                    q.append((c, node, prob / len(children), time + 1))
        return 0.0

