using namespace std;

class Solution {
public:
    double frogPosition(int n, vector<vector<int>>& edges, int t, int target) {
        vector<vector<int>> adj(n + 1);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        queue<array<double,2>> probs;
        queue<pair<int,int>> nodes;
        nodes.push({1, 0});
        probs.push({1.0, 0});
        vector<bool> seen(n + 1, false);
        seen[1] = true;
        while (!nodes.empty()) {
            auto [node, time] = nodes.front(); nodes.pop();
            auto [prob, _] = probs.front(); probs.pop();
            int children = 0;
            for (int nb : adj[node]) if (!seen[nb]) children++;
            if (node == target) {
                if (time == t || (time < t && children == 0)) return prob;
                return 0.0;
            }
            if (time < t) {
                for (int nb : adj[node]) {
                    if (!seen[nb]) {
                        seen[nb] = true;
                        nodes.push({nb, time + 1});
                        probs.push({prob / children, time + 1});
                    }
                }
            }
        }
        return 0.0;
    }
};

