class Solution {
    public double frogPosition(int n, int[][] edges, int t, int target) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        Deque<long[]> nodes = new ArrayDeque<>();
        Deque<Double> probs = new ArrayDeque<>();
        boolean[] seen = new boolean[n + 1];
        nodes.push(new long[]{1, 0});
        probs.push(1.0);
        seen[1] = true;
        while (!nodes.isEmpty()) {
            long[] cur = nodes.poll();
            int node = (int) cur[0], time = (int) cur[1];
            double prob = probs.poll();
            int children = 0;
            for (int nb : adj.get(node)) if (!seen[nb]) children++;
            if (node == target) {
                if (time == t || (time < t && children == 0)) return prob;
                return 0.0;
            }
            if (time < t) {
                for (int nb : adj.get(node)) {
                    if (!seen[nb]) {
                        seen[nb] = true;
                        nodes.push(new long[]{nb, time + 1});
                        probs.push(prob / children);
                    }
                }
            }
        }
        return 0.0;
    }
}

