import java.util.*;

class Solution {
    private List<List<Integer>> adj;
    private int t, target;

    private double dfs(int node, int par, int depth, double prob) {
        int children = 0;
        for (int nb : adj.get(node)) if (nb != par) children++;
        if (node == target)
            return (depth == t || (depth < t && children == 0)) ? prob : 0.0;
        if (depth >= t) return 0.0;
        for (int nb : adj.get(node)) {
            if (nb != par) {
                double r = dfs(nb, node, depth + 1, prob / children);
                if (r > 0) return r;
            }
        }
        return 0.0;
    }

    public double frogPosition(int n, int[][] edges, int t, int target) {
        this.t = t; this.target = target;
        adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        return dfs(1, 0, 0, 1.0);
    }
}

